package api

import (
	"context"
	_ "embed"
	"net/http"
	"net/url"
)

// ManifestAPIVersion is the group and version of the plane's manifest kinds. It is
// versioned apart from the HTTP API's /v1, and is not the operator's wingsmith.dev group.
const ManifestAPIVersion = "plane.wingsmith.dev/v1alpha1"

// ManifestSchema is the plane's JSON Schema for the manifest kinds, with the
// x-immutable and x-defaulted markers apply and diff read. Regenerated by
// scripts/manifest-schema.py and checked in CI.
//
//go:embed manifest-schema.json
var ManifestSchema []byte

// ManifestKinds maps each kind to its collection in /v1/manifests.
var ManifestKinds = map[string]string{
	"Workload": "workloads",
	"Endpoint": "endpoints",
	"Artifact": "artifacts",
}

// Manifest is one object as the plane renders it, kept generic: the CLI prints and
// diffs manifests, it does not interpret them.
type Manifest map[string]any

// Manifest reads one object by namespace and name. An empty project reads a
// public Artifact, the only kind without a namespace.
func (c *Client) Manifest(ctx context.Context, collection, project, name string) (Manifest, error) {
	path := "/v1/manifests/" + collection
	if project != "" {
		path += "/" + url.PathEscape(project)
	}
	var out Manifest
	err := c.get(ctx, path+"/"+url.PathEscape(name), nil, &out)
	return out, err
}

// ApplyOptions are a PUT's optional parts: a dry run, an If-Match revision, the
// field manager (the plane defaults it to wings-cli) and a forced takeover from
// another manager.
type ApplyOptions struct {
	DryRun       bool
	IfMatch      string
	FieldManager string
	Force        bool
}

// Apply results, from the plane's X-Wingsmith-Result header.
const (
	ApplyCreated    = "created"
	ApplyConfigured = "configured"
	ApplyUnchanged  = "unchanged"
)

// ApplyManifest creates or replaces one Workload or Endpoint with PUT and returns
// the object as the plane now holds it (or would, on a dry run) and whether it was
// created, configured or unchanged.
func (c *Client) ApplyManifest(ctx context.Context, collection, project, name string, m Manifest, opts ApplyOptions) (Manifest, string, error) {
	path := "/v1/manifests/" + collection + "/" + url.PathEscape(project) + "/" + url.PathEscape(name)
	q := url.Values{}
	if opts.DryRun {
		q.Set("dryRun", "All")
	}
	if opts.FieldManager != "" {
		q.Set("fieldManager", opts.FieldManager)
	}
	if opts.Force {
		q.Set("force", "true")
	}
	var headers map[string]string
	if opts.IfMatch != "" {
		headers = map[string]string{"If-Match": opts.IfMatch}
	}
	var out Manifest
	resp, err := c.sendResponse(ctx, http.MethodPut, path, q, m, headers, &out)
	if err != nil {
		return out, "", err
	}
	result := resp.Header.Get("X-Wingsmith-Result")
	if result == "" {
		result = ApplyConfigured
		if resp.StatusCode == http.StatusCreated {
			result = ApplyCreated
		}
	}
	return out, result, nil
}
